def gen(rng):
    def fmt(g, k):
        n = len(g)
        return f'{n} {k}\n' + '\n'.join(' '.join(map(str, r)) for r in g)

    def rnd(n, hi):
        return [[rng.randint(0, hi) for _ in range(n)] for _ in range(n)]

    tests = [
        fmt([[6, 4], [8, 7]], 1),
        fmt([[4]], 3),
        fmt([[0, 0], [0, 0]], 2),
        fmt([[5, 5], [5, 5]], 8),
        fmt([[1, 9, 9], [1, 5, 1], [1, 1, 1]], 2),
        fmt([[7] * 3 for _ in range(3)], 8),
    ]
    for n in (1, 2, 3, 4):
        for k in (1, 2, 3, 5, 8):
            tests.append(fmt(rnd(n, rng.choice([1, 9])), k))
    for _ in range(4):
        tests.append(fmt(rnd(4, 3), rng.randint(2, 8)))
    n = 500
    tests.append(fmt(rnd(n, 10**4), 8))
    tests.append(fmt([[10**4] * n for _ in range(n)], 8))
    tests.append(fmt(rnd(n, 1), 8))
    g = [[0] * n for _ in range(n)]
    for i in range(4):
        for j in range(4):
            g[200 + i][300 + j] = rng.randint(9000, 10**4)
    tests.append(fmt(g, 8))
    g = [[rng.randint(0, 3) for _ in range(n)] for _ in range(n)]
    for i in range(0, 20, 2):
        g[i][i] = 10**4
    tests.append(fmt(g, 1))
    tests.append(fmt(rnd(n, 10**4), 5))
    return tests
